parameters.jsCode:
return [
  {
    json: {
      status: "duplicate",
      message: "Duplicate lead detected. Lead was not added again."
    }
  }
];

const raw = $json.text;

let lead;

try {
  lead = JSON.parse(raw);
} catch (error) {
  throw new Error("AI response was not valid JSON: " + raw);
}

// Get the original customer message from the Webhook
const originalMessage =
  $('Webhook').item.json.body.message || '';

const message = originalMessage.toLowerCase();

// Deterministic timeframe detection
const timeframePatterns = [
  /\bas soon as possible\b/,
  /\basap\b/,
  /\bimmediately\b/,
  /\bright away\b/,
  /\bnow\b/,
  /\btoday\b/,
  /\btomorrow\b/,
  /\bwithin\s+\w+\s+(day|days|week|weeks|month|months)\b/,
  /\bnext\s+(day|week|month|year)\b/,
  /\bthis\s+(week|month|summer|fall|winter|spring|year)\b/,
  /\bin\s+(january|february|march|april|may|june|july|august|september|october|november|december)\b/,
  /\bby\s+\w+\b/
];

if (timeframePatterns.some(pattern => pattern.test(message))) {
  lead.has_specific_timeframe = true;
}

// Deterministic lead score
let score = 0;

if (lead.has_active_leak) score += 25;
if (lead.has_damage) score += 15;
if (lead.requests_estimate) score += 25;
if (lead.has_specific_timeframe) score += 20;
if (lead.comparing_options) score += 15;
if (lead.just_researching) score += 5;

score = Math.max(0, Math.min(100, score));

// Determine temperature
let temperature;

if (score >= 80) {
  temperature = "HOT";
} else if (score >= 50) {
  temperature = "WARM";
} else {
  temperature = "COLD";
}

lead.lead_score = score;
lead.lead_temperature = temperature;

// Score breakdown
const reasons = [];

if (lead.has_active_leak) reasons.push("Active leak (+25)");
if (lead.has_damage) reasons.push("Roof damage (+15)");
if (lead.requests_estimate) reasons.push("Estimate requested (+25)");
if (lead.has_specific_timeframe) reasons.push("Specific timeframe (+20)");
if (lead.comparing_options) reasons.push("Comparing options (+15)");
if (lead.just_researching) reasons.push("Researching (+5)");

lead.score_breakdown = reasons.join(", ");

return [
  {
    json: lead
  }
];
